"""List utility; splits a /list/ robustly into first & rest.

  Args:
      tokens: the list of tokens.
  Returns:
      Tuple of first token, and list of remaining.
  """
def FirstRest(tokens: Any) -> object {
    assert isinstance(tokens, `list);
    if not tokens {
        first = None;
        rest = [];
    } else {
        first = tokens[0];
        rest = tokens[1:];
    }
    return (first, rest);
}

"""Count unique items.

    Args:
        a (List): list of lists.
        b (List): list of lists.

    Returns:
        count (int): number of elements of a in b.
    """
def count_a_in_b_unique(a: Any, b: Any) -> object {
    count = 0;
    for el in a {
        if (el in b) {
            count += 1;
        }
    }
    return count;
}

"""Get query parameter of a URL."""
def get_query(string: Any, pos: Any = 1) -> object {
    try {
        return string.split("?")[pos];
    } except IndexError {
        if (pos == 1) {
            return "";
        } else {
            return string;
        }
    }
}

