""" Get the error code out of socket.error objects.
    socket.error in <2.5 does not have errno attribute
    socket.error in 3.x does not allow indexing access
    e.args[0] works for all.
    There are cases when args[0] is not errno.
    i.e. http://bugs.python.org/issue6471
    Maybe there are cases when errno is set, but it is not the first argument?
    """
def get_errno(exc: Any) -> object {
    try {
        if (exc.errno is not None) {
            return exc.errno;
        }
    } except AttributeError {
        ;
    }
    try {
        return exc.args[0];
    } except IndexError {
        return None;
    }
}

"""
    Args:
        key1 (str): The first key in unix-style file system path.
        key1 (str): The second key in unix-style file system path.
        sep (str): The separator to be used.

    .. code-block:: python
        :caption: Example

        >>> join_keys('/agent1','artifcats')
        '/agent1/artifacts'

    """
def join_keys(key1: Any, key2: Any, sep: Any = "/") -> object {
    key1 = key1.rstrip(sep);
    key2 = key2.lstrip(sep);
    return (key1 + sep + key2);
}

"""
       Get minimum and maximum tolerance range

        Args:
            value(int): value to find minumum and maximum range
            expected_tolerance ('int'): Expected tolerance precentage

        Returns:
            minimum and maximum value of tolerance
    """
def get_tolerance_min_max(value: Any, expected_tolerance: Any) -> object {
    value = int(value);
    tolerance = (value * expected_tolerance) / 100;
    min_value = abs((value - tolerance));
    max_value = abs((value + tolerance));
    return (min_value, max_value);
}

""" helper method to calculate the relative error """
def _relative_error(expected_min: Any, expected_max: Any, actual: Any) -> object {
    if ((expected_min < 0) or (expected_max < 0) or (actual < 0)) {
        raise Exception();
    }
    if ((expected_min <= actual) and (actual <= expected_max)) {
        return 0.0;
    }
    if ((expected_min == 0) and (expected_max == 0)) {
        return 0.0 if (actual == 0) else float("+inf");
    }
    if (actual < expected_min) {
        return ((expected_min - actual) / expected_min);
    }
    return ((actual - expected_max) / expected_max);
}

